/// <summary>
/// The <c>AVAWHSCloseContainerProfileDbt_Extension</c> represents a extension of WHSCloseContainerProfile table.
/// </summary>
/// <remarks>
/// AVA_7360_8266_ContainerPrint
/// </remarks>
[
    ExtensionOf(tableStr(WHSCloseContainerProfile))
]
final class AVAWHSCloseContainerProfileDbt_Extension
{
}

Method.Source:
/// <summary>
/// display Methode for the printer name
/// </summary>
/// <returns>
/// Returns the Name of the printer
/// </returns>
display public PrinterName avaPrinterName()
{
    SRSPrintDestinationSettings printJobSettings;
    PrinterName                 printerName;

    printJobSettings = new SRSPrintDestinationSettings(this.AVAPrinter);

    if (this.PrintContainerContents != NoYes::No)
    {
        if (printJobSettings.printMediumType() == SRSPrintMediumType::Printer)
        {
            printerName = printJobSettings.printerName();
        }
        else
        {
            printerName = strFmt('%1', printJobSettings.printMediumType());
        }
    }

    return printerName;
}

/// <summary>
/// Get the Printer Setting from rable
/// </summary>
/// <returns>
/// Returns the Printer settings for the closing container profil
/// </returns>
public SRSPrintDestinationSettings avaGetPrinterSettings()
{
    SRSPrintDestinationSettings printDestinationSettings;

    if (this.PrintContainerContents != NoYes::No)
    {
        printDestinationSettings = new SRSPrintDestinationSettings(this.AVAPrinter);
    }

    return printDestinationSettings;
}

/// <summary>
/// The <c>AVAWHSCloseContainerProfileDbt_Extension</c> represents a extension of WHSCloseContainerProfile table.
/// </summary>
/// <remarks>
/// AVA_7360_8266_ContainerPrint
/// </remarks>
public void avaSetupPrinter()
{
    SRSPrintDestinationSettings printJobSettings;

    printJobSettings = new SRSPrintDestinationSettings(this.AVAPrinter);

    SrsReportRunUtil::showSettingsDialog(printJobSettings);

    this.AVAPrinter = printJobSettings.pack();
}

/// <summary>
/// CoC for canPrintContainerContents
/// </summary>
/// <returns>
/// returns if it can print or not
/// </returns>
public boolean canPrintContainerContents()
{
    boolean                                 avaCanPrint;

    avaCanPrint = next canPrintContainerContents();

    //Call now because no other option in WHSContainerTale::closeContainerUsingParam(...)
    AVAPrintContainerLabelHelper::checkAndPrintContainerLabel(this);

    return avaCanPrint;
}

/// <summary>
/// CoC for validateWrite
/// </summary>
/// <returns>
/// returns if the validation for saving
/// </returns>
public boolean validateWrite()
{
    boolean ret;

    ret = next validateWrite();

    if (!ret
     && (this.AVAPrinter                != this.orig().AVAPrinter
      || this.AVAPrintContainerLabel    != this.orig().AVAPrintContainerLabel))
    {
        if (this.crossCheck())
        {
            ret = true;
        }
    }

    return ret;
}

private boolean crossCheck()
{
    boolean ret;

    ret = true;

    if (this.ManifestAtContainerClose && this.ManifestRequirementsForContainer == WHSManifestRequirement::None)
    {
        ret = false;
    }

    if (this.ContainerClosingWorkCreationProcess == WHSWarehouseContainerClosingWorkCreationProcess::Automatic)
    {
        if (this.PrintPackingSlip)
        {
            ret = false;
        }

        if (this.DefaultFinalShipLoc)
        {
            ret = false;
        }

        WHSParameters warehouseParameters = WHSParameters::find();

        if (warehouseParameters.PackingLocType)
        {
            ret = false;
        }
    }
    else if (this.ContainerClosingWorkCreationProcess == WHSWarehouseContainerClosingWorkCreationProcess::None && this.WorkTemplateCode)
    {
        ret = false;
    }

    if (this.PrintPackingSlipAsynchronously && !this.PackingSlipPostingParameters)
    {
        ret = false;
    }

    switch (this.WarehouseGroupAll)
    {
        case WhsWarehouseGroupAll::Group:
            if (!this.WarehouseGroupId)
            {
                ret = false;
            }
            break;
    }

    return ret;
}
